# Rule functions: each returns (new_text, count)
def css_px(s):
    pat = re.compile(r'(font-size\s*:\s*)(\d+(?:\.\d+)?)px')
    n = [0]
    def rep(m):
        v = float(m.group(2))
        if v < 14:
            n[0] += 1
            return m.group(1) + '14px'
        return m.group(0)
    return pat.sub(rep, s), n[0]

def css_rpx(s):
    pat = re.compile(r'(font-size\s*:\s*)(\d+(?:\.\d+)?)rpx')
    n = [0]
    def rep(m):
        v = float(m.group(2))
        if v < 28:
            n[0] += 1
            return m.group(1) + '28rpx'
        return m.group(0)
    return pat.sub(rep, s), n[0]

def echarts_js(s):
    pat = re.compile(r'(fontSize\s*:\s*)(\d+(?:\.\d+)?)')
    n = [0]
    def rep(m):
        v = float(m.group(2))
        if v < 14:
            n[0] += 1
            return m.group(1) + '14'
        return m.group(0)
    return pat.sub(rep, s), n[0]

def svg_attr(s):
    pat = re.compile(r"(setAttribute\(\s*['\"]font-size['\"]\s*,\s*['\"])(\d+(?:\.\d+)?)(['\"])")
